    SkillGroup = apps.get_model("honaryaar", "SkillGroup")
    Skill = apps.get_model("honaryaar", "Skill")
    Profile = apps.get_model("honaryaar", "Profile")
    ProfileSkill = apps.get_model("honaryaar", "ProfileSkill")
    groups = {}
    for item in SKILL_GROUPS:
        groups[item["slug"]] = SkillGroup.objects.create(
            slug=item["slug"],
            title=item["title"],
            priority=item["priority"],
        )
    skills = {}
    for item in SKILLS:
        skills[item["slug"]] = Skill.objects.create(
            slug=item["slug"],
            title=item["title"],
            group=groups[item["group"]],
        )
    general = groups["general"]
    for profile in Profile.objects.all():
        chosen = SAMPLE_SKILL_LEVELS.get(profile.slug, {})
        seen = set()
        for title in profile.skills or []:
            slug = LEGACY_SKILL_TITLES.get(title)
            if slug:
                skill = skills[slug]
            else:
                extra = "extra-" + hashlib.sha1(title.encode()).hexdigest()[:10]
                skill = skills.get(extra)
                if skill is None:
                    skill = Skill.objects.create(slug=extra, title=str(title)[:80], group=general)
                    skills[extra] = skill
            if skill.pk in seen:
                continue
            seen.add(skill.pk)
            ProfileSkill.objects.create(
                profile=profile,
                skill=skill,
                level=chosen.get(title, 2),
            )


